    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = next((v for row in g for v in row if any(x != v for rr in g for x in rr)), 0)
    sep = next((r for r,row in enumerate(g) if len(set(row)) == 1 and r > 0), None)
    if sep is not None:
        # Divider partitions the grid; mark the empty row on its far side,
        # opposite the nearest colored object.
        objects = [r for r in range(h) if r != sep and any(v != bg and v != g[sep][0] for v in g[r])]
        if objects:
            if min(objects) > sep:
                target = min(objects) - 1
            else:
                target = max(objects) + 1
            if 0 <= target < h:
                g[target] = [8] * w
        return g
    # Left border guide: mark the background immediately to the left of
    # the object's left extent, but only on rows not occupied by object.
    occupied = [(r,c) for r in range(h) for c in range(1,w) if g[r][c] != bg]
    if occupied:
        left = min(c for r,c in occupied)
        for r in range(h):
            if not any(g[r][c] != bg for c in range(1,w)):
                g[r][left-1] = 8
    return g
